magiccheck(struct magic_set *ms, struct magic *m, file_regex_t **m_cache)
{
        uint64_t l = m->value.q;
        uint64_t v;
        float fl, fv;
        double dl, dv;
        int matched;
        union VALUETYPE *p = &ms->ms_value;

        switch (m->type) {
        case FILE_BYTE:
                v = p->b;
                break;

        case FILE_SHORT:
        case FILE_BESHORT:
        case FILE_LESHORT:
        case FILE_MSDOSDATE:
        case FILE_LEMSDOSDATE:
        case FILE_BEMSDOSDATE:
        case FILE_MSDOSTIME:
        case FILE_LEMSDOSTIME:
        case FILE_BEMSDOSTIME:
                v = p->h;
                break;

        case FILE_LONG:
        case FILE_BELONG:
        case FILE_LELONG:
        case FILE_MELONG:
        case FILE_DATE:
        case FILE_BEDATE:
        case FILE_LEDATE:
        case FILE_MEDATE:
        case FILE_LDATE:
        case FILE_BELDATE:
        case FILE_LELDATE:
        case FILE_MELDATE:
                v = p->l;
                break;

        case FILE_QUAD:
        case FILE_LEQUAD:
        case FILE_BEQUAD:
        case FILE_QDATE:
        case FILE_BEQDATE:
        case FILE_LEQDATE:
        case FILE_QLDATE:
        case FILE_BEQLDATE:
        case FILE_LEQLDATE:
        case FILE_QWDATE:
        case FILE_BEQWDATE:
        case FILE_LEQWDATE:
        case FILE_OFFSET:
                v = p->q;
                break;

        case FILE_FLOAT:
        case FILE_BEFLOAT:
        case FILE_LEFLOAT:
                fl = m->value.f;
                fv = p->f;
                switch (m->reln) {
                case 'x':
                        matched = 1;
                        break;

                case '!':
                        matched = fv != fl;
                        break;

                case '=':
                        matched = fv == fl;
                        break;

                case '>':
                        matched = fv > fl;
                        break;

                case '<':
                        matched = fv < fl;
                        break;

                default:
                        file_magerror(ms, "cannot happen with float: "
                            "invalid relation `%c'", m->reln);
                        return -1;
                }
                return matched;

        case FILE_DOUBLE:
        case FILE_BEDOUBLE:
        case FILE_LEDOUBLE:
                dl = m->value.d;
                dv = p->d;
                switch (m->reln) {
                case 'x':
                        matched = 1;
                        break;

                case '!':
                        matched = dv != dl;
                        break;

                case '=':
                        matched = dv == dl;
                        break;

                case '>':
                        matched = dv > dl;
                        break;

                case '<':
                        matched = dv < dl;
                        break;

                default:
                        file_magerror(ms, "cannot happen with double: "
                            "invalid relation `%c'", m->reln);
                        return -1;
                }
                return matched;

        case FILE_DEFAULT:
        case FILE_CLEAR:
                l = 0;
                v = 0;
                break;

        case FILE_STRING:
        case FILE_PSTRING:
        case FILE_OCTAL:
                l = 0;
                v = file_strncmp(m->value.s, p->s, CAST(size_t, m->vallen),
                    sizeof(p->s), m->str_flags);
                break;

        case FILE_BESTRING16:
        case FILE_LESTRING16:
                l = 0;
                v = file_strncmp16(m->value.s, p->s, CAST(size_t, m->vallen),
                    sizeof(p->s), m->str_flags);
                break;

        case FILE_SEARCH: { /* search ms->search.s for the string m->value.s */
                size_t slen;
                size_t idx;

                if (ms->search.s == NULL)
                        return 0;

                slen = MIN(m->vallen, sizeof(m->value.s));
                l = 0;
                v = 0;
#ifdef HAVE_MEMMEM
                if (slen > 0 && m->str_flags == 0) {
                        const char *found;
                        idx = m->str_range + slen;
                        if (m->str_range == 0 || ms->search.s_len < idx)
                                idx = ms->search.s_len;
                        found = CAST(const char *, memmem(ms->search.s, idx,
                            m->value.s, slen));
                        if (!found) {
                                v = 1;
                                break;
                        }
                        idx = found - ms->search.s;
                        ms->search.offset += idx;
                        ms->search.rm_len = ms->search.s_len - idx;
                        break;
                }
#endif

                for (idx = 0; m->str_range == 0 || idx < m->str_range; idx++) {
                        if (slen + idx > ms->search.s_len) {
                                v = 1;
                                break;
                        }

                        v = file_strncmp(m->value.s, ms->search.s + idx, slen,
                            ms->search.s_len - idx, m->str_flags);
                        if (v == 0) {   /* found match */
                                ms->search.offset += idx;
                                ms->search.rm_len = ms->search.s_len - idx;
                                break;
                        }
                }
                break;
        }
        case FILE_REGEX: {
                int rc;
                file_regex_t *rx = *m_cache;
                const char *search;
                regmatch_t pmatch;
                size_t slen = ms->search.s_len;
                char *copy;

                if (ms->search.s == NULL)
                        return 0;

                if (rx == NULL) {
                        rx = *m_cache = alloc_regex(ms, m);
                        if (rx == NULL)
                                return -1;
                }
                l = 0;
                if (slen != 0) {
                    copy = CAST(char *, malloc(slen));
                    if (copy == NULL)  {
                        file_error(ms, errno,
                            "can't allocate %" SIZE_T_FORMAT "u bytes",
                            slen);
                        return -1;
                    }
                    memcpy(copy, ms->search.s, slen);
                    copy[--slen] = '\0';
                    search = copy;
                } else {
                    search = CCAST(char *, "");
                    copy = NULL;
                }
                rc = file_regexec(ms, rx, RCAST(const char *, search),
                    1, &pmatch, 0);
                free(copy);
                switch (rc) {
                case 0:
                        ms->search.s += CAST(int, pmatch.rm_so);
                        ms->search.offset += CAST(size_t, pmatch.rm_so);
                        ms->search.rm_len = CAST(size_t,
                            pmatch.rm_eo - pmatch.rm_so);
                        v = 0;
                        break;

                case REG_NOMATCH:
                        v = 1;
                        break;

                default:
                        return -1;
                }
                break;
        }
        case FILE_USE:
                return ms->ms_value.q != 0;
        case FILE_NAME:
        case FILE_INDIRECT:
                return 1;
        case FILE_DER:
                matched = der_cmp(ms, m);
                if (matched == -1) {
                        if ((ms->flags & MAGIC_DEBUG) != 0) {
                                (void) fprintf(stderr,
                                    "EOF comparing DER entries\n");
                        }
                        return 0;
                }
                return matched;
        case FILE_GUID:
                l = 0;
                v = memcmp(m->value.guid, p->guid, sizeof(p->guid));
                break;
        default:
                file_magerror(ms, "invalid type %d in magiccheck()", m->type);
                return -1;
        }

        v = file_signextend(ms, m, v);

        switch (m->reln) {
        case 'x':
